css:
.win{border-width:2px;border-color:#8a5a2c}
.win.focused{border-color:#2a1a0e}
.win > .bar .title{letter-spacing:.04em}
.licon .tile{border-radius:9px}
.menubar,.composer,.dock{backdrop-filter:blur(10px) saturate(1.1)}
.hs-sea{position:absolute;inset:0;background:url('{{asset:sea}}') center / cover no-repeat}
.hs-ship{position:absolute;left:8%;bottom:9%;width:min(30vw,420px);aspect-ratio:1;
  background:url('{{asset:ship}}') center / contain no-repeat;transform-origin:50% 90%;
  animation:hsSail 60s linear infinite, hsBob 5s ease-in-out infinite}
@keyframes hsSail{0%{left:-30%}100%{left:105%}}
@keyframes hsBob{0%,100%{transform:rotate(-2.5deg) translateY(0)}50%{transform:rotate(2.5deg) translateY(10px)}}
.hs-wave{position:absolute;left:-10%;right:-10%;height:12%;
  background:radial-gradient(60px 18px at 60px 0,transparent 97%,var(--c) 100%) 0 0 / 120px 100% repeat-x;
  animation:hsWave var(--t) linear infinite}
.hs-wave.w1{--c:rgba(27,143,196,.55);--t:9s;bottom:6%}
.hs-wave.w2{--c:rgba(15,111,166,.75);--t:6s;bottom:0;animation-direction:reverse}
@keyframes hsWave{to{background-position:120px 0}}
.hs-flag{position:absolute;right:3%;top:10%;width:120px;aspect-ratio:3/2;background:#15110e url('{{asset:roger}}') center / 70% no-repeat;
  border-radius:2px 8px 8px 2px;box-shadow:0 8px 20px -8px rgba(0,0,0,.5);transform-origin:0 50%;animation:hsFlap 3s ease-in-out infinite;opacity:.92}
@keyframes hsFlap{0%,100%{transform:skewY(-3deg) scaleX(1)}50%{transform:skewY(3deg) scaleX(.94)}}
@media (prefers-reduced-motion:reduce){.hs-ship,.hs-wave,.hs-flag{animation:none}.hs-ship{left:8%}}
